INSERT INTO `incident_record` VALUES (2,'2026-07-19 12:00:00.000','PIM 1','Kendala operasional (Utilitas/peralatan pendukung operasional)','asd','Joko Susilo',NULL,NULL,NULL,NULL),(3,'2026-07-01 18:30:00.000','PIM 3','Kehilangan barang di dalam mushola','- 19:08 : Pelapor memasuki area mushalla Lt. 1 Barat. - 19:17 : Pelapor keluar area mushalla Lt. 1 Barat. - 19:18 : Pelapor kembali memasuki area mushalla Lt. 1 Barat. - 19:23 : Pelapor meninggalkan area mushalla Lt. 1 Barat. - 19:31 : Perempuan dress putih mengambil jam milik pelapor. - 19:34 : Terduga perempuan dress putih meninggalkan area mushalla Lt. 1 Barat. - 19:35 : Terduga perempuan dress putih naik eskalator ke Lt. 2 Barat. - 19:36 : Terduga perempuan dress putih memasuki Booth Pondok Indah Residence. Nb : Setelah berkoordinasi dengan Spv security Bpk. Fauzi, terduga perempuan dress putih tersebut karyawan Booth Pondok Indah Residence dan sedang dalam pengecekan oleh Spv security Bpk. Fauzi dan team.','Brandon Kafi Mills',NULL,NULL,NULL,NULL),(4,'2026-07-02 13:24:00.000','PIM 3','Kendala Lift dan Eskalator','Escalator LG-Timur Turun ke B1 Timur off di karenakan tali sepatu pengunjung tersangkut, berkoordinasi dengan Team ME Bpk. Hendrik.','Riyan Veriana','Escalator Sudah Normal kembali','2026-07-02 13:39:00.000','00:15:00',NULL),(5,'2026-07-02 16:06:00.000','PIM 3','Kendala Lift dan Eskalator','Maintenance LS-5-WM Oleh Team BSL.','Rian Abdul Rahman','Lift Sudah Normal Kembali.','2026-07-02 18:04:00.000','01:58:00',NULL),(6,'2026-07-02 20:00:03.000','PIM 3','Kendala Lift dan Eskalator','LS-4-WM Error Dengan Sendirinya Tidak Ada Yang Terjebak, Sudah Dikoordinasikan Dengan Team ME Bpk. Rustam','M. Diki Syawaludin','Lift Sudah Normal Kembali.','2026-07-05 11:36:00.000','63:35:57',NULL),(7,'2026-07-02 17:07:00.000','Street Gallery','Kendala Lift dan Eskalator','Eskalator 4 naik ke lantai 2 trouble. Info dari Petugas ME (Bpk. Ahmad R), dikarenakan eskalator tidak bisa direstart menunggu team BSL untuk memperbaik